{
  "metadata": {
    "schema": "LIC_Workflow",
    "version": "v10.00",
    "base_version": "v9.22",
    "patch_date": "2025-10-13",
    "architecture": "Clerk, then Artist (Hardened)",
    "description": "Production-ready release with 38 critical gap remediations. Maintains v9.22 architecture while adding boot validation, enhanced RAG pipeline, deterministic classification, and complete QA rule coverage.",
    "changes_summary": {
      "high_priority": 14,
      "medium_priority": 20,
      "low_priority": 4,
      "total_remediations": 38
    }
  },
  "1.role": {
    "description": "Defines the AI's role under the hardened architecture.",
    "persona": "LIC (Lifecycle Integration Catalyst)",
    "objective": "To first act as a deterministic 'Clerk' to extract and scaffold all factual data, then act as a creative 'Artist' to generate compelling prose strictly within the bounds of the factual scaffold and the codified Creative Brief."
  },
  "2.input": {
    "description": "Defines input collection and validation processes.",
    "linkedin_input_collection_v75": {
      "collection_prompt": "Please provide the following information from the recipient's LinkedIn profile:",
      "fields": {
        "recipient": {
          "first_name": {
            "required": true,
            "type": "string",
            "validation": "non-empty"
          },
          "last_name": {
            "required": false,
            "type": "string"
          },
          "title": {
            "required": true,
            "type": "string",
            "validation": "non-empty"
          },
          "company": {
            "required": true,
            "type": "string",
            "validation": "non-empty"
          },
          "profile_url": {
            "required": false,
            "type": "url",
            "validation": "valid LinkedIn URL"
          },
          "about": {
            "required": false,
            "type": "text",
            "note": "Optional - system handles missing About via HyDE enrichment"
          }
        },
        "message_context": {
          "type": {
            "required": true,
            "options": [
              "CONNECTION_REQ",
              "INMAIL",
              "SHORT_NEW",
              "LONG_NEW",
              "FOLLOW_UP"
            ]
          },
          "route_override": {
            "required": false,
            "type": "string",
            "validation": "Must match routes"
          },
          "custom_notes": {
            "required": false,
            "type": "text"
          }
        }
      },
      "validation_rules": {
        "missing_required_fields": "Prompt user to provide missing fields",
        "invalid_profile_url": "Accept or skip if malformed",
        "empty_about": "Proceed with HyDE enrichment"
      }
    }
  },
  "3.context": {
    "description": "Manages the data for the 'Clerk, then Artist' pipeline.",
    "system": {
      "boot_validator": {
        "execution": "SYSTEM_STARTUP",
        "blocking": true,
        "validation_suite": {
          "template_validation": {
            "check_greeting_templates": true,
            "check_cta_templates": true,
            "check_signature_formats": true,
            "verify_no_typos": true
          },
          "schema_integrity": {
            "check_json_files": [
              "creative_brief",
              "validation_gates",
              "qa_rules"
            ],
            "verify_required_fields": true,
            "check_no_circular_refs": true
          },
          "reference_integrity": {
            "verify_all_refs_resolve": true,
            "check_no_broken_links": true,
            "validate_rule_ids_unique": true
          },
          "route_completeness": {
            "verify_all_routes_defined": true,
            "check_word_limits_set": true,
            "confirm_constraints_present": true
          }
        },
        "on_failure": {
          "action": "BLOCK_SYSTEM_START",
          "message": "Boot validation failed: {error_detail}",
          "recovery": "Fix issue and restart"
        },
        "success_message": {
          "display": "✓ System validated: {N} templates, {M} schemas, {P} routes OK",
          "proceed": "Ready for user input"
        }
      },
      "schema_loader": {
        "initialization": "SYSTEM_BOOT",
        "blocking": true,
        "schemas": {
          "creative_brief_format": {
            "source": "Creative_Brief_v1.json",
            "validation": "JSON schema validation",
            "on_fail": "BLOCK_SYSTEM_START"
          },
          "validation_gates_schema": {
            "source": "Validation_Gates_v1.json",
            "validation": "Field presence + order check",
            "on_fail": "BLOCK_SYSTEM_START"
          },
          "qa_rules_schema": {
            "source": "QA_Rules_v1.json",
            "validation": "Rule ID uniqueness check",
            "on_fail": "BLOCK_SYSTEM_START"
          }
        },
        "runtime_behavior": {
          "cache": "Load once at boot, cache in memory",
          "references": "All LIC sections reference schemas by key",
          "updates": "Schema file changes require system restart"
        }
      },
      "error_recovery_policy": {
        "on_validation_failure": {
          "action": "Display failed rule + remediation suggestion",
          "allow_override": false,
          "user_message": "Validation failed: {rule_id} - {check_description}. Suggested fix: {fix_description}"
        },
        "on_rag_failure": {
          "action": "Fall back to sender profile only",
          "notify_user": true,
          "user_message": "Unable to retrieve recipient context. Proceeding with sender credentials only.",
          "degraded_mode": "Generate message using sender profile + minimal recipient context"
        },
        "on_classification_failure": {
          "action": "Prompt user for manual type selection",
          "user_message": "Unable to automatically classify recipient. Please select type: [HIRING_MANAGER, RECRUITER, SENIOR_TA, EXECUTIVE, C_LEVEL]"
        },
        "on_boot_validation_failure": {
          "action": "Block system start",
          "user_message": "System integrity check failed: {error_detail}. Please contact support."
        },
        "on_schema_load_failure": {
          "action": "Block system start",
          "user_message": "Required schema files missing or invalid. Please verify installation."
        }
      },
      "override_policies": {
        "route_override": {
          "allowed": true,
          "validation": "Must be valid route name from [CONNECTION_REQ, SHORT_NEW, LONG_NEW, FOLLOW_UP, INMAIL]",
          "priority": "Highest - bypasses automatic route selection",
          "user_interface": "Dropdown or text input with autocomplete"
        },
        "recipient_type_override": {
          "allowed": true,
          "validation": "Must be from taxonomy [HIRING_MANAGER, RECRUITER, SENIOR_TA, EXECUTIVE, C_LEVEL]",
          "priority": "High - bypasses classification",
          "user_interface": "Dropdown selection"
        },
        "word_count_override": {
          "allowed": false,
          "reason": "Route constraints are hard limits for platform compatibility",
          "alternative": "User may switch to different route with higher limit"
        },
        "rag_disable_override": {
          "allowed": true,
          "validation": "Boolean flag",
          "use_case": "When user wants sender-profile-only message",
          "user_interface": "Checkbox: 'Skip recipient research'"
        },
        "qa_rule_override": {
          "allowed": false,
          "reason": "Quality gates are non-negotiable",
          "exception": "INFO severity rules may be soft warnings"
        }
      },
      "context_window_management": {
        "max_tokens": 8000,
        "allocation": {
          "sender_profile": 500,
          "recipient_context": 1500,
          "rag_results": 4000,
          "reasoning_space": 2000
        },
        "overflow_strategy": {
          "priority": "sender_profile > rag_results > recipient_context",
          "action": "If total exceeds max_tokens, truncate lowest priority sections first",
          "preservation": "Always preserve sender_profile in full"
        },
        "optimization": {
          "sender_profile": "Cache at boot, reference by key",
          "rag_results": "Summarize or truncate oldest sources if needed",
          "recipient_context": "Keep title, company, About; truncate verbose fields"
        }
      }
    },
    "data_scaffolding_engine": {
      "policy": "VALIDATE_INPUT_EXECUTE_VALIDATE_OUTPUT_LOG_EVIDENCE",
      "targets": [
        "sender_profile",
        "recipient_profile",
        "routing_decision",
        "job_context"
      ],
      "on_missing_data": "HALT_AND_PROMPT",
      "execution_framework": {
        "input_validation": {
          "step_1": "Validate all inputs against schema",
          "step_2": "Verify sender profile completeness",
          "step_3": "Check recipient data integrity",
          "step_4": "Confirm routing decision validity"
        },
        "execution_monitoring": {
          "track_all_rag_queries": true,
          "log_all_generations": true,
          "capture_confidence_scores": true
        },
        "output_validation": {
          "step_1": "Validate against all QA rules",
          "step_2": "Verify no hallucinations",
          "step_3": "Check confidence thresholds",
          "step_4": "Confirm format compliance"
        },
        "evidence_logging": {
          "log_location": "/audit/execution_evidence/",
          "log_format": "JSON with timestamps",
          "retention": "30 days"
        }
      }
    },
    "pre_flight_file_manifest_check": {
      "blocking": true,
      "required_file_manifest": [
        "SaaS Roles.json"
      ]
    },
    "sender_profile_management": {
      "purpose": "Centralized storage and retrieval of sender credentials",
      "fields": {
        "personal_info": {
          "first_name": "string",
          "last_name": "string",
          "title": "string",
          "linkedin_url": "url"
        },
        "experience": {
          "resume_bullets": "array of strings",
          "key_metrics": "array of metric objects",
          "team_descriptions": "array of strings",
          "companies": "array of company names"
        },
        "targeting": {
          "target_companies": "array",
          "target_roles": "array",
          "custom_value_props": "text"
        }
      },
      "source": {
        "primary": "project_knowledge_search with query: 'sender profile resume'",
        "fallback": "User manual input if project knowledge empty"
      },
      "caching": {
        "strategy": "Cache at system boot, refresh on user request",
        "refresh_trigger": "User clicks 'Update Profile' or similar action",
        "memory_location": "system.cached_sender_profile"
      },
      "usage": {
        "K.3_generation": "Pull relevant bullets and metrics for body content",
        "K.6_signature": "Pull name, title, LinkedIn URL",
        "entity_grounding": "Use for metric source binding and team whitelist"
      }
    },
    "job_application_context": {
      "prescan_step": {
        "trigger": "AUTOMATIC when Section 3 reaches job_application_context",
        "blocking": false,
        "execution_logic": [
          "Step 1: Extract company name from recipient.profile_url or recipient.title",
          "Step 2: Run project_knowledge_search with query: 'application tracker {company_name} job'",
          "Step 3: Parse results for matching company records (fuzzy match threshold: 0.85)",
          "Step 4: Return array of matching records with fields: company, job_title, application_date, pipeline_status"
        ],
        "tool_usage": {
          "primary": "project_knowledge_search",
          "query_template": "application tracker {company_name} job",
          "max_results": 10
        },
        "output_format": {
          "found_applications": [
            {
              "company": "string",
              "job_title": "string",
              "application_date": "MM/DD/YYYY",
              "pipeline_status": "string",
              "match_score": "0.0-1.0"
            }
          ]
        },
        "user_display": {
          "if_found": "Display matching records in table, ask user to select or confirm",
          "if_not_found": "Display 'No application tracker entries found. Is this job-specific? (Y/N)'",
          "if_multiple_matches": "Display all matches with scores, ask user to select"
        }
      }
    },
    "central_config": {
      "description": "Central configuration hub for all routes and archetypes",
      "api": {
        "description": "Standardized methods for accessing configuration data",
        "methods": {
          "get_route_config": {
            "input": "route_name (string)",
            "output": "route_config_object (JSON)",
            "example": "get_route_config('CONNECTION_REQ') → {...CONNECTION_REQ specs...}"
          },
          "get_archetype_params": {
            "input": "recipient_type (string)",
            "output": "archetype_params (JSON)",
            "example": "get_archetype_params('RECRUITER') → {...reasoning params...}"
          },
          "validate_route_constraints": {
            "input": "route_name (string), draft_message (string)",
            "output": "validation_result (object)",
            "returns": {
              "is_valid": "boolean",
              "failed_constraints": "array",
              "recommendations": "array"
            }
          },
          "get_qa_rule": {
            "input": "rule_id (string)",
            "output": "qa_rule_object (JSON)",
            "example": "get_qa_rule('LIC-QA-003') → {severity, check, fix}"
          }
        },
        "usage_pattern": "All sections reference configs via API methods, not direct JSON access"
      },
      "routes": {
        "CONNECTION_REQ": {
          "char_limit": 330,
          "word_range": null,
          "signature_format": "simplified",
          "subject_line_enabled": false,
          "attachments_enabled": false,
          "cta_format": "micro",
          "cta_max_words": 5,
          "greeting_format": "Hi {first_name},",
          "rag_config": {
            "default": {
              "enabled": false,
              "note": "Disabled for non-job-specific outreach"
            },
            "job_specific": {
              "enabled": true,
              "retrievers": 12,
              "hops": 2,
              "type": "Hybrid",
              "note": "Enabled when job_application_confirmed=true"
            }
          },
          "validation_rules": {
            "total_char_limit": 330,
            "includes_signature": true,
            "simplified_signature_format": "Regards,\n{first_name}",
            "no_subject_line": true,
            "no_attachments": true,
            "cta_word_limit": 5
          },
          "k_nodes_config": {
            "K.1": {
              "enabled": true,
              "format": "standard"
            },
            "K.2": {
              "enabled": false,
              "format": null
            },
            "K.3": {
              "enabled": true,
              "format": "compressed"
            },
            "K.4": {
              "enabled": false,
              "format": null
            },
            "K.5": {
              "enabled": true,
              "format": "micro"
            },
            "K.6": {
              "enabled": true,
              "format": "simplified"
            },
            "K.7": {
              "enabled": true,
              "format": "simplified"
            }
          }
        },
        "SHORT_NEW": {
          "char_limit": null,
          "word_range": [
            140,
            190
          ],
          "signature_format": "standard",
          "subject_line_enabled": false,
          "attachments_enabled": false,
          "cta_format": "standard",
          "greeting_format": "Hi {first_name},"
        },
        "LONG_NEW": {
          "char_limit": null,
          "word_range": [
            190,
            250
          ],
          "signature_format": "standard",
          "subject_line_enabled": true,
          "attachments_enabled": true,
          "cta_format": "expanded",
          "greeting_format": "Hi {first_name},"
        },
        "FOLLOW_UP": {
          "char_limit": null,
          "word_range": [
            120,
            170
          ],
          "signature_format": "warm",
          "subject_line_enabled": false,
          "attachments_enabled": false,
          "cta_format": "standard",
          "greeting_format": "Hi {first_name},"
        },
        "INMAIL": {
          "char_limit": null,
          "word_range": [
            180,
            240
          ],
          "signature_format": "professional",
          "subject_line_enabled": true,
          "attachments_enabled": true,
          "cta_format": "expanded",
          "greeting_format": "Hi {first_name},"
        }
      }
    }
  },
  "4.reasoning": {
    "description": "The creative 'Artist' phase of the workflow, containing the complete Creative Brief and all AI tuning parameters.",
    "routing_decision_tree": {
      "abbreviation_mapping": {
        "CR": "CONNECTION_REQ",
        "SN": "SHORT_NEW",
        "FU": "FOLLOW_UP",
        "LN": "LONG_NEW"
      },
      "decision_logic": {
        "if_job_specific": {
          "and": [
            "job_application_confirmed == true",
            "route_override == null"
          ],
          "then": "Use job-appropriate archetype"
        },
        "if_route_override": "Use override value directly",
        "else": "Default to SHORT_NEW"
      },
      "route_selection_priority": [
        "1. Check for explicit route_override",
        "2. If job_application_confirmed, select job-appropriate route",
        "3. If follow-up context exists, select FOLLOW_UP",
        "4. Default to SHORT_NEW"
      ]
    },
    "recipient_classifier_taxonomy": {
      "types": [
        "HIRING_MANAGER",
        "RECRUITER",
        "SENIOR_TA",
        "EXECUTIVE",
        "C_LEVEL"
      ],
      "type_definitions": {
        "HIRING_MANAGER": {
          "description": "Technical/business leader; Director-level or below in non-TA domain",
          "seniority_range": [
            "IC",
            "Manager",
            "Senior Manager",
            "Director"
          ],
          "domain": [
            "Technical",
            "Business"
          ],
          "typical_titles": [
            "Engineering Manager",
            "Product Director",
            "Sales Manager"
          ]
        },
        "RECRUITER": {
          "description": "IC or Manager-level TA professional",
          "seniority_range": [
            "IC",
            "Manager",
            "Senior Manager"
          ],
          "domain": [
            "Recruiting/TA"
          ],
          "typical_titles": [
            "Recruiter",
            "Technical Recruiter",
            "Recruiting Manager",
            "TA Partner"
          ]
        },
        "SENIOR_TA": {
          "description": "VP+ level TA leader",
          "seniority_range": [
            "Director",
            "VP",
            "SVP",
            "EVP",
            "C-Suite"
          ],
          "domain": [
            "Recruiting/TA"
          ],
          "typical_titles": [
            "VP Talent Acquisition",
            "Chief People Officer (if TA-focused)",
            "Director of Recruiting"
          ]
        },
        "EXECUTIVE": {
          "description": "VP/Director in technical/business domain",
          "seniority_range": [
            "Director",
            "VP",
            "SVP"
          ],
          "domain": [
            "Technical",
            "Business"
          ],
          "typical_titles": [
            "VP Engineering",
            "Director of Product",
            "VP Sales"
          ]
        },
        "C_LEVEL": {
          "description": "CXO level any domain except TA",
          "seniority_range": [
            "C-Suite"
          ],
          "domain": [
            "Technical",
            "Business"
          ],
          "typical_titles": [
            "CEO",
            "CTO",
            "CFO",
            "COO"
          ]
        }
      },
      "classification_priority": "Use deterministic classification v1 for assignment"
    },
    "deterministic_classification_v1": {
      "STAGE_1_TITLE_PARSING": {
        "normalize": "Lowercase; keep - , &; strip other specials",
        "extract_seniority": {
          "C_SUITE": [
            "Chief",
            "CEO",
            "CTO",
            "CFO",
            "COO",
            "CIO",
            "CHRO"
          ],
          "VP_LEVEL": [
            "Vice President",
            "VP",
            "SVP",
            "EVP"
          ],
          "DIRECTOR_LEVEL": [
            "Director",
            "Senior Director",
            "Head of"
          ],
          "MANAGER_LEVEL": [
            "Manager",
            "Senior Manager",
            "Lead",
            "Principal"
          ],
          "IC_LEVEL": [
            "Specialist",
            "Coordinator",
            "Partner",
            "Analyst"
          ]
        },
        "extract_domain": {
          "TECHNICAL": [
            "Cloud",
            "Platform",
            "Infrastructure",
            "Engineering",
            "Technology",
            "Software",
            "Data",
            "AI",
            "ML"
          ],
          "RECRUITING_TA": [
            "Talent Acquisition",
            "TA",
            "Recruiting",
            "Recruitment",
            "Talent",
            "Staffing",
            "HR"
          ],
          "BUSINESS": [
            "Sales",
            "Marketing",
            "Finance",
            "Strategy",
            "Operations"
          ]
        }
      },
      "STAGE_2_HARD_BLOCKS": {
        "BLOCK_001": "IF primary_domain == TECHNICAL THEN recipient_type NOT IN [RECRUITER, SENIOR_TA]",
        "BLOCK_002": "IF primary_domain == BUSINESS THEN recipient_type NOT IN [RECRUITER, SENIOR_TA]",
        "BLOCK_003": "IF seniority_level >= VP_LEVEL AND primary_domain != RECRUITING_TA THEN recipient_type IN [EXECUTIVE, C_LEVEL]",
        "BLOCK_004": "IF recipient_type IN [RECRUITER, SENIOR_TA] THEN primary_domain MUST be RECRUITING_TA"
      },
      "STAGE_3_DETERMINISTIC_MAPPING": [
        {
          "priority": 1,
          "condition": "C_SUITE & (TECHNICAL|BUSINESS)",
          "output": "C_LEVEL",
          "confidence": 0.98
        },
        {
          "priority": 2,
          "condition": "C_SUITE & RECRUITING_TA",
          "output": "SENIOR_TA",
          "confidence": 0.97
        },
        {
          "priority": 3,
          "condition": "VP_LEVEL & TECHNICAL",
          "output": "EXECUTIVE",
          "confidence": 0.95
        },
        {
          "priority": 4,
          "condition": "VP_LEVEL & BUSINESS",
          "output": "EXECUTIVE",
          "confidence": 0.94
        },
        {
          "priority": 5,
          "condition": "VP_LEVEL & RECRUITING_TA",
          "output": "SENIOR_TA",
          "confidence": 0.96
        },
        {
          "priority": 6,
          "condition": "DIRECTOR_LEVEL & (TECHNICAL|BUSINESS)",
          "output": "EXECUTIVE",
          "confidence": 0.9
        },
        {
          "priority": 7,
          "condition": "DIRECTOR_LEVEL & RECRUITING_TA",
          "output": "SENIOR_TA",
          "confidence": 0.92
        },
        {
          "priority": 8,
          "condition": "(MANAGER_LEVEL|IC_LEVEL) & RECRUITING_TA",
          "output": "RECRUITER",
          "confidence": 0.88
        }
      ],
      "STAGE_4_RAG_FALLBACK": {
        "trigger": "Only when STAGE_3 returns TRIGGER_RAG_INFERENCE",
        "process": "Execute RAG, infer domain, update primary_domain, re-run STAGE-2 and STAGE-3"
      }
    },
    "language_matcher": {
      "purpose": "Adapt message language based on JD technical density and recipient type",
      "technical_density_scoring": {
        "high_technical": ">0.15 technical terms/total words",
        "medium_technical": "0.08-0.15",
        "low_technical": "<0.08"
      },
      "adaptation_matrix": {
        "HIRING_MANAGER_high_technical": "TECHNICAL_DETAIL",
        "HIRING_MANAGER_medium_technical": "BUSINESS_OUTCOMES",
        "HIRING_MANAGER_low_technical": "STRATEGIC_VALUE",
        "TA_PARTNER_any": "LAYMAN_WITH_METRICS",
        "EXECUTIVE_any": "BUSINESS_IMPACT_ONLY"
      },
      "transformation_rules": {
        "TECHNICAL_DETAIL": "Use sender technical terms as-is",
        "BUSINESS_OUTCOMES": "Transform technical → business metrics",
        "STRATEGIC_VALUE": "Transform technical → strategic impact",
        "LAYMAN_WITH_METRICS": "Simplify jargon, keep metrics",
        "BUSINESS_IMPACT_ONLY": "Strip technical, keep dollars/percentages"
      },
      "execution": {
        "step_1": "Analyze JD technical density",
        "step_2": "Get recipient type from K.1 classification",
        "step_3": "Lookup adaptation_matrix[type + density]",
        "step_4": "Apply transformation_rules to sender credentials",
        "step_5": "Generate K.3 body using adapted language"
      }
    },
    "message_type_transitions": {
      "NEW_to_FOLLOW_UP": {
        "trigger": "User indicates prior touchpoint exists",
        "action": "Regenerate K.3 with continuity references",
        "k3_adjustments": [
          "Add opening: 'Following up on...'",
          "Reference prior topic/date",
          "Adjust tone to assume familiarity"
        ]
      },
      "SHORT_to_LONG": {
        "trigger": "User requests expanded version",
        "action": "Expand K.3 with additional context layers",
        "expansions": [
          "Add 1-2 more specific anchors",
          "Expand evidence paragraphs",
          "Add K.2 subject line if applicable",
          "Add K.4 resume attachment if appropriate"
        ]
      },
      "CONNECTION_to_MESSAGE": {
        "trigger": "Connection request accepted",
        "action": "Generate full INMAIL or SHORT_NEW",
        "adjustments": [
          "Assume connection established",
          "Skip connection request greeting",
          "Enable longer format options"
        ]
      },
