    "rag_pipeline_v75": {
      "description": "6-stage RAG validation pipeline with HyDE, hybrid recall, cross-encoder reranking, self-RAG, episodic memory, knowledge graph, and few-shot injection",
      "stage_0_hyde": {
        "enabled": true,
        "trigger": "recipient_profile.about == NULL or length < 50",
        "method": "Generate hypothetical profile using title + company + domain",
        "purpose": "Enrich weak/missing About fields for better semantic search",
        "constraints": {
          "no_fabricated_employers": true,
          "no_fabricated_dates": true,
          "validation": "LIC-QA-041 and LIC-QA-066"
        }
      },
      "stage_1_hybrid_recall": {
        "web_search_calls": 6,
        "internal_sources": [
          "project_knowledge_search",
          "conversation_search"
        ],
        "queries": "6 diverse queries: recipient background, company initiatives, industry context, shared connections, news, domain",
        "output": "raw_results_pool (~20-30 sources)"
      },
      "stage_2_cross_encoder_reranking": {
        "model": "cross-encoder/ms-marco-MiniLM-L-6-v2",
        "threshold": 0.75,
        "weights": {
          "relevance": 0.35,
          "authority": 0.2,
          "recency": 0.45
        },
        "recency_decay": "Linear decay from 1.0 (today) to 0.0 (45 days ago)",
        "anchor_temporal_window_days": 45,
        "output": "top_8_sources (CE score ≥ 0.75)",
        "enforcement": "LIC-QA-062: Drop CE score < 0.75"
      },
      "stage_3_self_rag": {
        "max_hops": 6,
        "min_hops": 2,
        "hop_trigger": "Detect knowledge gaps, ambiguous claims, insufficient anchor density",
        "per_hop": {
          "gap_analysis": "Identify missing info",
          "query_generation": "Formulate targeted follow-up",
          "retrieval": "Execute web_search or internal tool",
          "rerank": "Apply cross-encoder to new results",
          "integration": "Merge into evidence pool"
        },
        "termination": "Stop when gaps closed or max_hops reached",
        "enforcement": "LIC-QA-069: Hop cap respected"
      },
      "stage_4_episodic_memory": {
        "enabled": true,
        "trigger": "route == FOLLOW_UP",
        "method": "Retrieve patterns from past sender→recipient exchanges",
        "tool": "conversation_search",
        "max_results": 5
      },
      "stage_5_knowledge_graph": {
        "enabled": true,
        "queries": [
          "shared_connections",
          "company_relationships",
          "industry_overlaps"
        ],
        "purpose": "Identify non-obvious connection points",
        "enforcement": "LIC-QA-036: Resolve graph conflicts"
      },
      "stage_6_few_shot_injection": {
        "enabled": true,
        "examples": "3-5 high-quality message bodies for similar recipient types",
        "purpose": "Guide tone, structure, anchor placement",
        "source": "project_knowledge_search with query: 'example messages {recipient_type}'"
      }
    },
    "rag_validation_framework": {
      "validation_modes": {
        "strict": {
          "description": "For critical claims and metrics",
          "requirements": {
            "min_sources": 2,
            "min_confidence": 0.95,
            "exact_match_required": true,
            "cross_validation": true
          }
        },
        "balanced": {
          "description": "For standard personalization",
          "requirements": {
            "min_sources": 1,
            "min_confidence": 0.85,
            "semantic_match_ok": true,
            "cross_validation": false
          }
        },
        "permissive": {
          "description": "For conversational elements",
          "requirements": {
            "min_sources": 1,
            "min_confidence": 0.7,
            "inference_allowed": true,
            "cross_validation": false
          }
        }
      },
      "claim_type_mapping": {
        "metrics": "strict",
        "company_names": "strict",
        "achievements": "strict",
        "industry_trends": "balanced",
        "general_observations": "permissive"
      },
      "validation_workflow": {
        "step_1": "Classify each claim by type",
        "step_2": "Apply appropriate validation mode",
        "step_3": "Score confidence per claim",
        "step_4": "Calculate aggregate confidence",
        "step_5": "BLOCK if below mode threshold"
      },
      "confidence_scoring": {
        "per_claim_minimum": 0.8,
        "aggregate_minimum": 0.95,
        "enforcement": "BLOCK delivery if below threshold",
        "scoring_methodology": {
          "claim_extraction": {
            "method": "Split K.3 body into atomic claims",
            "splitters": [
              ".",
              "and",
              "while",
              "by"
            ]
          },
          "per_claim_scoring": {
            "base_score": 1.0,
            "deductions": [
              {
                "condition": "No RAG source found",
                "penalty": -0.5
              },
              {
                "condition": "Metric has no source mapping",
                "penalty": -0.4
              },
              {
                "condition": "Company not in whitelist",
                "penalty": -1.0
              },
              {
                "condition": "Role terminology drifted (similarity <0.92)",
                "penalty": -0.3
              },
              {
                "condition": "Context coherence <0.80",
                "penalty": -0.25
              }
            ],
            "minimum_claim_score": 0.8
          },
          "aggregate_confidence": {
            "calculation": "Average of all individual claim scores",
            "formula": "sum(claim_scores) / count(claims)",
            "minimum_threshold": 0.95
          }
        },
        "threshold_enforcement": {
          "on_below_threshold": {
            "action": "REJECT",
            "error_message": "Aggregate confidence {score} below threshold 0.95",
            "regeneration_strategy": "Apply stricter constraints"
          },
          "on_above_threshold": {
            "action": "APPROVE",
            "log_message": "K.3 body APPROVED: Aggregate confidence {score}/1.00 ≥ 0.95"
          }
        }
      }
    },
    "entity_grounding_framework": {
      "pre_generation_extraction": {
        "purpose": "Extract and lock all critical entities before generation",
        "targets": [
          "sender_employment_history",
          "validated_companies",
          "role_titles",
          "metrics_with_sources"
        ],
        "constraint": "Artist can ONLY use entities from validated whitelist",
