                ],
                "company": "Company Name",
                "source_bullet": "reducing client onboarding timelines by forty percent",
                "full_context": "Full sentence with ±20 words of context"
              }
            ]
          },
          "constraint": "EVERY metric in K.3 must map to metric_source_map entry"
        }
      },
      "team_whitelist": {
        "purpose": "Prevent generic team descriptions and role drift",
        "source": "project_knowledge_search with query: 'sender experience roles teams responsibilities'",
        "format": {
          "whitelist_entry": {
            "exact_team_name": "string",
            "exact_role_description": "string",
            "company_context": "string",
            "allowed_synonyms": "array"
          }
        },
        "validation": {
          "method": "Semantic similarity check",
          "threshold": 0.92,
          "rule": "All team mentions in K.3 must have ≥0.92 similarity to whitelist entry"
        },
        "enforcement": {
          "on_violation": "REJECT generation and trigger regeneration",
          "error_message": "Team description '{description}' does not match whitelist. Use exact wording from sender profile."
        },
        "example": {
          "whitelisted": "led a cross-functional team of 8 engineers and 3 designers",
          "rejected": "managed a team",
          "reason": "Too generic, lacks specificity"
        }
      },
      "generation_constraints": {
        "LIC-QA-032": {
          "name": "Company Name Validation",
          "phase": "PRE_GENERATION",
          "rule": "Extract ALL companies from sender history → validated_list",
          "enforcement": "HARD BLOCK on unlisted companies"
        },
        "LIC-QA-038": {
          "name": "Entity Cross-Reference",
          "phase": "POST_GENERATION",
          "rule": "Every proper noun must exist in RAG sources",
          "enforcement": "REJECT and regenerate if hallucinated"
        },
        "LIC-QA-041": {
          "name": "Metric Source Validation",
          "phase": "POST_GENERATION",
          "rule": "Every metric must map to source document",
          "enforcement": "REJECT if unmapped metric found"
        },
        "LIC-QA-042": {
          "name": "Role Drift Detection",
          "phase": "POST_GENERATION",
          "rule": "Team descriptions must match source (≥0.92 similarity)",
          "enforcement": "REJECT if generic terms used"
