  "6.validation": {
    "description": "Complete validation framework with all QA rules and enforcement gates.",
    "ascii_hygiene": {
      "purpose": "Ensure LinkedIn compatibility by converting all Unicode to ASCII",
      "execution_point": "POST_GENERATION, before final assembly",
      "rules": {
        "no_smart_quotes": true,
        "no_em_dashes": true,
        "no_en_dashes": true,
